args.sql:
WITH ra AS (
  SELECT id, name, ST_PointOnSurface(geom) AS pt FROM residential_areas WHERE name = '南湾营融康苑' ORDER BY id LIMIT 1
), sv AS (
  SELECT v.id, v.geom FROM ra, LATERAL (SELECT id, geom FROM walk_vertices WHERE in_main ORDER BY geom <-> ra.pt LIMIT 1) v
), dd AS (
  SELECT * FROM pgr_drivingDistance('SELECT id, source, target, cost_m AS cost, cost_m AS reverse_cost FROM walk_edges', (SELECT id FROM sv), 1000, directed => false)
), schools AS (
  SELECT p.id, p.name, p.geom FROM pois p WHERE p.category='amenity' AND p.subtype='school' AND p.name LIKE '%中学%'
), snapped AS (
  SELECT s.id, s.name, s.geom, (SELECT v.id FROM walk_vertices v WHERE v.in_main ORDER BY v.geom <-> s.geom LIMIT 1) AS vid FROM schools s
)
SELECT (SELECT count(*) FROM snapped sn JOIN dd ON dd.node = sn.vid) AS reachable_schools,
       (SELECT count(*) FROM schools) AS total_schools,
       (SELECT id FROM sv) AS start_vertex

